import{_ as i,l as n,o as e,c as s,v as t,p as l,x as r,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"交易所时间戳与经纪商时间戳","description":"","frontmatter":{"title":"交易所时间戳与经纪商时间戳","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/exchange-broker-clocks.md","filePath":"quant/exchange-broker-clocks.md","lastUpdated":1789023840000}'),h={name:"quant/exchange-broker-clocks.md"};function E(B,a,m,u,P,_){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="交易所时间戳与经纪商时间戳" tabindex="-1">交易所时间戳与经纪商时间戳 <a class="header-anchor" href="#交易所时间戳与经纪商时间戳" aria-label="Permalink to &quot;交易所时间戳与经纪商时间戳&quot;">​</a></h1><div class="epigraph"><p>行情记录上的时间字段可能是撮合引擎的时钟，也可能是经纪商或行情商写入的时钟。字段名字都叫 timestamp 时，对齐仍然没有定义。</p><footer>—— 据 Hasbrouck 对逐笔数据时间戳来源与精度的讨论；对照 FINRA / 交易所对时钟同步的公开要求</footer></div><p><a href="/quant/sip-vs-direct">SIP vs 直连</a>选定了管道。<a href="/quant/exchange-vs-broker-ts">交易系统</a>已经从订单路径写过两套业务时钟。本课的缺口是<strong>行情契约里的字段</strong>：数据商文件中的 <code>timestamp</code> 究竟是交易所匹配时间、交易所发送时间、SIP 处理时间，还是经纪商收到时间。研究常把它们当成同一个「事件时间」，于是跨所领先滞后、有效价差、甚至日 bar 的开盘都会错。后课 PTP/GPS 写如何把不同引擎的钟校准到同一时间基；本课先要求把字段读懂。不重复订单状态机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一份直连 ITCH 可能带 matching engine timestamp。一份 SIP 可能带 SIP 收到各所报文的时间。一份经纪商推送可能带客户到达时间。三者都可以标成纳秒。精度不等于来源。用经纪商到达时间去重建本所簿的时间优先，等于用你的网络路径改写了市场。用 SIP 处理时间去算直连成交的中点，等于用慢钟给快事件贴标签。缺口是数据字典：每个源的每个时间字段映射到哪一种物理事件。</p><p>与系统课的差别：系统课决定生产 PnL 的主键；本课决定研究样本里「同一毫秒」的含义。两者应一致，但历史数据库往往只有数据商的一个戳，必须在文档里写清它是哪一种，而不是假定等于系统主键。</p><h3 id="发送时间、匹配时间、参与者时间" tabindex="-1">发送时间、匹配时间、参与者时间 <a class="header-anchor" href="#发送时间、匹配时间、参与者时间" aria-label="Permalink to &quot;发送时间、匹配时间、参与者时间&quot;">​</a></h3><p>匹配时间：引擎产生成交或报价更新的时刻，最接近价格形成。发送时间：报文离开交易所网关，已含内部排队。参与者/客户时间：你的网卡。监管时钟同步要求（后课）针对的是交易所与报告参与者，不是针对你的笔记本。研究领先滞后必须用匹配时间（并已校准）；延迟预算必须用参与者时间减匹配时间。用错字段，会把管道延迟当成价格发现。</p><p><span class="marginnote">TAQ 一类产品的时间戳定义随年代变。早期秒级、后来毫秒、再后来微纳秒，中间还换过源。拼接几十年样本必须读各期手册，不能假设字段不变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个数据集写一页契约：字段名、定义、时钟源、精度、是否单调、与序号的关系。重建簿只用匹配时间加序号。计算到达延迟时另存参与者时间。缺失匹配时间时，降级声明：结论只关于该馈送的到达过程，不是关于引擎内的价格发现。跨源合并前，先看后课对时；未对时的合并禁止做领先滞后。</p><p>检查：同一成交在交易所官方回放、SIP、经纪商三套文件上的三个戳，差的分布应合理（非负的传输延迟、SIP 多一跳）。若经纪商戳早于匹配时间，不是 alpha，是时钟未同步或字段填反。</p><h3 id="成交与报价戳必须成对定义" tabindex="-1">成交与报价戳必须成对定义 <a class="header-anchor" href="#成交与报价戳必须成对定义" aria-label="Permalink to &quot;成交与报价戳必须成对定义&quot;">​</a></h3><p>Lee–Ready / EMO 需要「成交前最后报价」。若成交用匹配时间、报价用 SIP 时间，最后报价可能是未来或过时。同源同一种时间字段，是方向分类的前提。碎片化下本所成交对本所匹配时间的报价，全国有效价差对 SIP 时间的 NBBO，两套会计分开报。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时间戳定义决定你把因果箭头画在哪。匹配时间上的报价更新导致随后成交，是价格形成。到达时间上的「报价晚于成交」，可能只是你的包后到。O&#39;Hara（2015）强调高频下「何时算一笔交易」本身是对象；对象先被字段定义，再被经济解释。把字段问题当成微观结构发现，会制造虚假的超前交易。</p><p><span class="marginnote">加密 websocket 的服务器时间常常是发送时间甚至应用层时间，不是撮合时间。永续标记价格还有自己的计算时钟。不要把股票 ITCH 的匹配时间假设套过去。</span></p>',17)),(e(),l(d,null,{default:r(()=>[c(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TB%0A%20%20ME%5B%22%E5%8C%B9%E9%85%8D%E5%BC%95%E6%93%8E%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20MT%5B%22%E5%8C%B9%E9%85%8D%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20MT%20--%3E%20SND%5B%22%E5%8F%91%E9%80%81%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20SND%20--%3E%20SIP%5B%22SIP%20%E5%A4%84%E7%90%86%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20SND%20--%3E%20CL%5B%22%E5%AE%A2%E6%88%B7%E5%88%B0%E8%BE%BE%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20MT%20--%3E%20PF%5B%22%E4%BB%B7%E6%A0%BC%E5%BD%A2%E6%88%90%E7%A0%94%E7%A9%B6%22%5D%0A%20%20CL%20--%3E%20LAT%5B%22%E5%BB%B6%E8%BF%9F%E8%AF%8A%E6%96%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="字段精度随产品年代变化" tabindex="-1">字段精度随产品年代变化 <a class="header-anchor" href="#字段精度随产品年代变化" aria-label="Permalink to &quot;字段精度随产品年代变化&quot;">​</a></h3><p>同一「TAQ timestamp」在不同年代可以是秒、毫秒或微纳秒，源也可能从 SIP 换到另一汇总。拼接长样本必须按手册分段，否则领先滞后是精度阶跃。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准振荡器，那是下一课。经纪商内部还有账本日期与业务截止，属于估值。债券 TRACE 的报告时间又是另一字段，见本课序最后一课。字段读错时，宁可不做领先滞后。</p><p><span class="marginnote">客户到达早于匹配时间，优先当字典填反或未对时，不当做信息优势。先修系统课的主键在研究库里必须能找到对应字段。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>timestamp 字段必须映射到匹配、发送、汇总或到达，精度不能代替定义。</li><li>价格发现用匹配时间；延迟预算用到达减匹配。</li><li>方向分类要求成交与报价同一字段定义。</li><li>客户戳早于匹配戳，优先当对时或字典错误。</li><li>历史产品字段随年代变，拼接要读手册。</li><li>出处：Hasbrouck 对微观结构数据手册式处理；O&#39;Hara, <em>Journal of Finance</em>, 2015；各 SIP / 交易所馈送规格。</li></ul>',7))])}const S=i(h,[["render",E]]);export{b as __pageData,S as default};
